#include <cctype>
#include <iostream>
#include <locale>
#include <string>

int main() {
    std::string line;
    if (!std::getline(std::cin, line)) return 1;
    if (line.size() < 1 || line.size() > 100) return 1;
    std::locale classic = std::locale::classic();
    long long alpha = 0;
    long long digit = 0;
    long long other = 0;
    for (char ch : line) {
        unsigned char code = static_cast<unsigned char>(ch);
        if (code < 32 || code > 126) return 1;
        if (std::isalpha(ch, classic)) {
            alpha++;
        } else if (std::isdigit(ch, classic)) {
            digit++;
        } else {
            other++;
        }
    }
    std::cout << "alpha=" << alpha << " digit=" << digit << " other=" << other << std::endl;
    return 0;
}
